-- ============================================================
-- Warehouse (Gold) layer - SYNTHETIC INVENTORY
-- Olist has no stock data, so this table is generated by
-- warehouse/generate_inventory.py from the real monthly sales.
-- Run AFTER the warehouse ETL (run_etl.py). Safe to re-run.
-- No FOREIGN KEY constraints on purpose: the ETL reloads the
-- dimensions, and the data quality checks verify the keys instead.
-- ============================================================

DROP TABLE IF EXISTS warehouse.fact_inventory;

CREATE TABLE warehouse.fact_inventory (
    product_key        integer NOT NULL,   -- -> warehouse.dim_product
    snapshot_date_key  integer NOT NULL,   -- -> warehouse.dim_date (last day of the month)
    opening_stock      integer NOT NULL,
    units_received     integer NOT NULL,   -- synthetic
    units_sold         integer NOT NULL,   -- real: valid-sale items of the month
    closing_stock      integer NOT NULL,   -- opening + received - sold
    reorder_level      integer NOT NULL,   -- synthetic
    is_low_stock       boolean NOT NULL,   -- closing_stock <= reorder_level
    PRIMARY KEY (product_key, snapshot_date_key)
);

CREATE INDEX idx_fact_inventory_date ON warehouse.fact_inventory (snapshot_date_key);

COMMENT ON TABLE warehouse.fact_inventory IS
    'SYNTHETIC monthly stock snapshot per product. units_sold is real; stock levels, receipts and reorder levels are simulated.';
